-- Removes Chinese from spare-part rows the catalog seed does not rewrite: 4 SKUs that carried a Chinese note
-- (renamed here, before the seed runs) and older parts outside the catalog ("Chinese / English" names keep the English half).
-- Every statement only rewrites a column that still contains Chinese, so text edited since is left alone.
WITH p(x) AS (SELECT '*[' || char(19968) || '-' || char(40959) || char(65281) || '-' || char(65374) || ']*') UPDATE "SparePart" SET "sku" = '21510-000177 (Yellow-Green)' WHERE "sku" LIKE '%21510-000177%' AND "sku" GLOB (SELECT x FROM p) AND NOT EXISTS (SELECT 1 FROM "SparePart" WHERE "sku" = '21510-000177 (Yellow-Green)');
WITH p(x) AS (SELECT '*[' || char(19968) || '-' || char(40959) || char(65281) || '-' || char(65374) || ']*') UPDATE "SparePart" SET "sku" = '21510-000179 (Yellow-Green)' WHERE "sku" LIKE '%21510-000179%' AND "sku" GLOB (SELECT x FROM p) AND NOT EXISTS (SELECT 1 FROM "SparePart" WHERE "sku" = '21510-000179 (Yellow-Green)');
